import {BY_ID,ENEMIES,MAPS,wavesFor} from './data.js';
export function routeInfo(points){let lengths=points.slice(1).map((p,i)=>Math.hypot(p[0]-points[i][0],p[1]-points[i][1]));return {lengths,total:lengths.reduce((a,b)=>a+b,0)};}
export function positionAt(points,d){for(let i=1;i<points.length;i++){let a=points[i-1],b=points[i],len=Math.hypot(b[0]-a[0],b[1]-a[1]);if(d<=len)return {x:a[0]+(b[0]-a[0])*Math.max(d,0)/len,y:a[1]+(b[1]-a[1])*Math.max(d,0)/len,flip:b[0]<a[0]};d-=len;}return {x:points.at(-1)[0],y:points.at(-1)[1],flip:false};}
export class Battle{
 constructor(mapIndex=0,saved=null){this.mapIndex=mapIndex;this.map=MAPS[mapIndex];this.route=routeInfo(this.map.points);this.waves=wavesFor(mapIndex);this.time=0;this.offerings=this.map.offerings;this.shield=this.map.shield;this.meter=0;this.wave=0;this.status='planning';this.shrines=[];this.enemies=[];this.effects=[];this.fields=[];this.queue=[];this.spawnTimer=0;this.id=0;this.boostUntil=0;this.kills=0;this.message='Choose a plot, then establish a shrine.';this.events=[];this.activeWaves=[];this.completedWaves=[];this.earlyCalls=0;this.interventions=0;this.usedDeities=[];if(saved&&saved.mapIndex===mapIndex){for(let k of ['time','offerings','shield','meter','wave','status','shrines','enemies','fields','queue','spawnTimer','id','boostUntil','kills','message','activeWaves','completedWaves','earlyCalls','interventions','usedDeities'])if(saved[k]!==undefined)this[k]=saved[k];}}
 snapshot(){let out={mapIndex:this.mapIndex};for(let k of ['time','offerings','shield','meter','wave','status','shrines','enemies','fields','queue','spawnTimer','id','boostUntil','kills','message','activeWaves','completedWaves','earlyCalls','interventions','usedDeities'])out[k]=this[k];return JSON.parse(JSON.stringify(out));}
 notify(type,text){this.events.push({type,text});this.message=text;}
 build(plot,deity){let d=BY_ID[deity];if(!d||this.shrines.some(s=>s.plot===plot)||!this.map.plots[plot]||this.offerings<d.cost||['won','lost'].includes(this.status))return false;this.offerings-=d.cost;if(!this.usedDeities.includes(deity))this.usedDeities.push(deity);this.shrines.push({plot,deity,level:1,cooldown:0,spent:d.cost});this.notify('build',`${d.name}’s shrine is established.`);return true;}
 upgrade(plot){let s=this.shrines.find(s=>s.plot===plot);if(!s||s.level>=3||['won','lost'].includes(this.status))return false;let cost=BY_ID[s.deity].upgrade[s.level-1];if(this.offerings<cost)return false;this.offerings-=cost;s.spent+=cost;s.level++;let [x,y]=this.map.plots[plot];this.effects.push({type:'upgrade',x,y,colour:BY_ID[s.deity].colour,life:1.6,max:1.6,level:s.level});this.notify('upgrade',`${BY_ID[s.deity].name}’s shrine is ${s.level===2?'Honoured':'Exalted'}.`);return true;}
 sell(plot){let s=this.shrines.find(s=>s.plot===plot);if(!s||['won','lost'].includes(this.status))return false;let refund=Math.floor(s.spent*.85);this.offerings+=refund;this.shrines=this.shrines.filter(t=>t!==s);this.notify('sell',`Offerings returned: ${refund}.`);return true;}
 canCallEarly(){return this.status==='fighting'&&this.wave<this.waves.length&&this.queue.length===0&&this.enemies.length>0&&this.activeWaves.length<2;}
 earlyReward(){return 20+Math.min(40,Math.floor(this.enemies.reduce((n,e)=>n+e.hp/e.maxHp*3,0)));}
 startWave(early=false){
  if(early?!this.canCallEarly():this.status!=='planning'||this.wave>=this.waves.length)return false;
  if(early){let reward=this.earlyReward();this.offerings+=reward;this.earlyCalls++;this.notify('early',`Called early. +${reward} offerings; two waves now overlap.`);}
  const next=this.wave+1;this.queue.push(...this.waves[this.wave].map(x=>({...x,waveId:next})));this.activeWaves.push(next);this.wave=next;this.status='fighting';this.spawnTimer=.4;
  this.notify('wave',this.wave===8?`${this.map.bossName}: “${this.map.quote}”`:`Wave ${this.wave} approaches.`);return true;
 }
 spawn(spec,distance=0){let base=ENEMIES[spec.type],scale=1+this.mapIndex*.16;let e={...base,...spec,id:++this.id,hp:base.hp*scale,maxHp:base.hp*scale,distance,slowUntil:0,wetUntil:0,rootUntil:0,revealUntil:0,pushUntil:0,copyUntil:0,stopped:false};if(base.boss){e.name=this.map.bossName;e.family=this.map.bossFamily??3;if(e.boon==='oath')e.armour=.7;}this.enemies.push(e);return e;}
 pos(e){return positionAt(this.map.points,e.distance);}
 near(e,x,y,r){let p=this.pos(e);return Math.hypot(p.x-x,p.y-y)<=r;}
 visible(e){return !(e.hidden||(e.boon==='night'&&Math.floor(this.time/5)%2===1))||e.revealUntil>this.time;}
 canAffect(e,id){return e.protection!==id&&e.hp>0;}
 hit(e,amount,id,ignoreVisibility=false){if(!this.canAffect(e,id)||(!ignoreVisibility&&!this.visible(e)))return false;let mult=e.boon==='iron'&&!e.stopped&&e.rootUntil<=this.time?.25:1;let armour=['agni','indra','varuna'].includes(id)?0:e.armour;e.hp-=amount*(1-armour)*mult;if(e.boon==='mirror'&&id==='indra'&&e.copyUntil<=this.time){e.copyUntil=this.time+4;this.spawn({type:'shade',waveId:e.waveId},Math.max(0,e.distance-45));this.spawn({type:'shade',waveId:e.waveId},Math.max(0,e.distance-85));this.notify('boon','Mayadhara has made two veiled copies!');}return true;}
 intervention(plot){let s=this.shrines.find(s=>s.plot===plot);if(!s||this.meter<100||this.status!=='fighting')return false;this.meter=0;this.interventions++;let id=s.deity;let enemies=[...this.enemies].filter(e=>this.canAffect(e,id));if(id==='saraswati'){this.boostUntil=this.time+8;for(let e of enemies)e.revealUntil=this.time+8;}else if(id==='indra'){for(let e of enemies.filter(e=>this.visible(e)).sort((a,b)=>b.hp-a.hp).slice(0,6)){this.hit(e,280,id);let p=this.pos(e);this.effects.push({type:'strike',...p,colour:BY_ID[id].colour,life:.8,max:.8});}}else for(let e of enemies){if(!this.visible(e))continue;if(id==='agni')this.hit(e,125,id);if(id==='varuna'){e.distance=Math.max(0,e.distance-170);e.wetUntil=this.time+6;e.slowUntil=this.time+6;this.hit(e,40,id);}if(id==='vayu'){e.distance=Math.max(0,e.distance-270);this.hit(e,35,id);}if(id==='prithvi')e.rootUntil=this.time+6;if(id==='durga'){this.hit(e,150,id);e.rootUntil=this.time+3;}}
 this.effects.push({type:'intervention',deity:id,x:600,y:320,colour:BY_ID[id].colour,life:1.2,max:1.2});this.notify('intervention',`${BY_ID[id].name} answers your call.`);return true;}
 animate(dt){for(let f of this.effects)f.life-=dt;this.effects=this.effects.filter(f=>f.life>0);}
 tick(dt){if(this.status!=='fighting')return;dt=Math.min(.1,Math.max(0,dt));this.time+=dt;this.spawnTimer-=dt;if(this.queue.length&&this.spawnTimer<=0){this.spawn(this.queue.shift());this.spawnTimer=this.wave<3?1.05:.85;}
 for(let e of this.enemies){e.stopped=false;if(e.boon==='seals')e.protection=['agni','varuna','indra'][Math.floor(this.time/8)%3];}
 // Wisdom reveals illusions. Divine protection blocks this deity's reveal effect too.
 for(let s of this.shrines){if(s.deity!=='saraswati')continue;let [x,y]=this.map.plots[s.plot],r=BY_ID.saraswati.range+(s.level-1)*16;for(let e of this.enemies)if(this.canAffect(e,'saraswati')&&this.near(e,x,y,r))e.revealUntil=this.time+.3;}
 for(let s of this.shrines.filter(s=>s.deity==='durga')){let [x,y]=this.map.plots[s.plot];let targets=this.enemies.filter(e=>!e.flying&&this.canAffect(e,'durga')&&this.visible(e)&&this.near(e,x,y,BY_ID.durga.range+(s.level-1)*12)).sort((a,b)=>b.distance-a.distance).slice(0,s.level);for(let e of targets)e.stopped=true;}
 for(let e of this.enemies){if(e.hp<=0)continue;if(!e.stopped&&e.rootUntil<=this.time)e.distance+=e.speed*(e.slowUntil>this.time?.52:1)*dt;}
 for(let field of this.fields){field.life-=dt;for(let e of this.enemies)if(this.near(e,field.x,field.y,field.radius))this.hit(e,field.damage*dt,'agni');}this.fields=this.fields.filter(f=>f.life>0);
 for(let s of this.shrines){let d=BY_ID[s.deity],[x,y]=this.map.plots[s.plot];let wisdom=this.shrines.filter(t=>t.deity==='saraswati'&&Math.hypot(this.map.plots[t.plot][0]-x,this.map.plots[t.plot][1]-y)<=BY_ID.saraswati.range+(t.level-1)*16).reduce((v,t)=>Math.max(v,.16*t.level),0);s.cooldown-=dt*(1+wisdom+(this.boostUntil>this.time?.6:0));if(s.cooldown>0)continue;let targets=this.enemies.filter(e=>this.canAffect(e,s.deity)&&this.visible(e)&&this.near(e,x,y,d.range+(s.level-1)*12)).sort((a,b)=>b.distance-a.distance);let e=targets[0];if(!e)continue;s.cooldown=d.rate;let p=this.pos(e);let damage=d.damage*(1+(s.level-1)*.65);this.effects.push({type:'shot',x,y,tx:p.x,ty:p.y,colour:d.colour,life:.65,max:.65,deity:s.deity,level:s.level});
 if(s.deity==='agni'){for(let t of this.enemies)if(this.near(t,p.x,p.y,38+s.level*7))this.hit(t,damage,'agni');if(s.level>1)this.fields.push({x:p.x,y:p.y,radius:42+s.level*5,damage:5*s.level,life:2.5});}
 else if(s.deity==='varuna'){this.hit(e,damage,'varuna');e.slowUntil=this.time+1.7+s.level*.4;e.wetUntil=this.time+4;if(s.level===3)for(let t of targets.slice(1,3)){this.hit(t,damage*.5,'varuna');t.slowUntil=this.time+2;t.wetUntil=this.time+4;}}
 else if(s.deity==='vayu'){this.hit(e,damage*(e.flying?1.8:1),'vayu');if(e.pushUntil<=this.time){e.distance=Math.max(0,e.distance-9-s.level*5);e.pushUntil=this.time+1.2;}if(s.level===3)for(let t of targets.slice(1,3))if(t.pushUntil<=this.time){t.distance=Math.max(0,t.distance-12);t.pushUntil=this.time+1.2;}}
 else if(s.deity==='prithvi'){this.hit(e,damage,'prithvi');e.rootUntil=Math.max(e.rootUntil,this.time+.38+s.level*.2);if(s.level===3)for(let t of targets.slice(1,3))t.rootUntil=this.time+.65;}
 else if(s.deity==='indra'){let wet=e.wetUntil>this.time;this.hit(e,damage*(wet?1.25:1),'indra');let hops=wet?s.level+1:s.level-1;for(let t of this.enemies.filter(t=>t!==e&&this.canAffect(t,'indra')&&this.visible(t)&&this.near(t,p.x,p.y,140)).sort((a,b)=>b.distance-a.distance).slice(0,hops)){this.hit(t,damage*.65,'indra');let q=this.pos(t);this.effects.push({type:'shot',x:p.x,y:p.y,tx:q.x,ty:q.y,colour:d.colour,life:.5,max:.5,deity:'indra',level:s.level,chain:true});}}
 else if(s.deity==='saraswati'){this.hit(e,damage,'saraswati');if(s.level===3){let echo=targets[1];if(echo){this.hit(echo,damage*.5,'saraswati');let q=this.pos(echo);this.effects.push({type:'shot',x,y,tx:q.x,ty:q.y,colour:d.colour,life:.7,max:.7,deity:s.deity,level:s.level});}}}
 else this.hit(e,damage,'durga');
 }
 let surviving=[];for(let e of this.enemies){if(e.hp<=0){this.offerings+=e.reward;this.meter=Math.min(100,this.meter+(e.boss?20:3));this.kills++;let p=this.pos(e);this.effects.push({type:'defeat',...p,colour:'#bd842b',life:.5,max:.5});}else if(e.distance>=this.route.total){this.shield=Math.max(0,this.shield-e.shield);this.notify('leak',`${e.name} reached the temple. Shield −${e.shield}.`);}else surviving.push(e);}this.enemies=surviving;
 if(this.shield<=0){this.status='lost';this.notify('lost','The temple shield has fallen. Your shrines remain standing.');return;}
 for(let waveId of [...this.activeWaves]){
  if(this.queue.some(e=>e.waveId===waveId)||this.enemies.some(e=>e.waveId===waveId))continue;
  this.activeWaves=this.activeWaves.filter(w=>w!==waveId);this.completedWaves.push(waveId);let bonus=55+waveId*5;this.offerings+=bonus;this.meter=Math.min(100,this.meter+12);this.notify('clear',`Wave ${waveId} survived. +${bonus} offerings.`);
 }
 if(!this.enemies.length&&!this.queue.length){if(this.wave>=this.waves.length){this.status='won';this.notify('won','The temple is safe. The light returns.');}else this.status='planning';}
 }
}
